package i18n

var configEN = map[string]string{
	"config.saved":                         "Configuration saved",
	"cmd.config.short":                     "View or update CLI default configuration",
	"cmd.config.long":                      "Inspect or update the endpoint, credentials, language, scene, output format, and TLS preferences stored on the current machine.",
	"cmd.config.examples":                  "./hyperbdrctl config get\n./hyperbdrctl config set \\\n  --host https://example:10443 \\\n  --username admin \\\n  --password secret",
	"cmd.config.usage_line":                "hyperbdrctl config <command> [flags]",
	"cmd.config.usage_notes":               "View the address, credentials, language, scene, and output format saved on the current machine:\n  hyperbdrctl config get\n\nInitialize or update the local default configuration:\n  hyperbdrctl config set \\\n    --host https://example:10443 \\\n    --username <username> \\\n    --password <password>\n\nIf you do not want to save the address or credentials to local configuration, set environment variables using the syntax for your current shell.\n\nFor complete flags, environment variables, and validation rules, continue with:\n  hyperbdrctl config get --help\n  hyperbdrctl config set --help\n\nConfiguration is read in the following priority order:\n  command-line flags > environment variables > config file > defaults\n\nAfter configuration, run the following commands to verify that subsequent commands use the new defaults:\n  hyperbdrctl config get\n  hyperbdrctl host list",
	"cmd.config.notes":                     "- Resolution precedence is command flag > environment variable > config file > default.\n- `config get` masks the saved password unless `--show-secret` is requested.",
	"cmd.config.workflow":                  "1. Run `config get` to inspect the current saved values and paths.\n2. Run `config set` when you need to change endpoint, credentials, or local defaults.\n3. Re-run `config get` before other commands depend on the updated defaults.",
	"cmd.config.related":                   "./hyperbdrctl config get\n./hyperbdrctl config set --help",
	"cmd.config.next_steps":                "./hyperbdrctl host list\n./hyperbdrctl boot-config get --id <host_id>",
	"cmd.config.get.short":                 "Show the saved local configuration",
	"cmd.config.get.long":                  "Read the saved local configuration plus the config file and token cache paths. Password remains masked unless `--show-secret` is requested.",
	"cmd.config.get.examples":              "./hyperbdrctl config get\n./hyperbdrctl config get --show-secret",
	"cmd.config.get.usage_line":            "hyperbdrctl config get [flags]",
	"cmd.config.get.usage_notes":           "Read the local configuration saved on the current machine and show the config file and token cache paths.\n\nView the saved configuration:\n  hyperbdrctl config get\n\nBy default, the saved password stays masked in the output.\n\nTo view the saved password in plain text:\n  hyperbdrctl config get --show-secret\n\nThis command only reads local files and does not call the remote API.\n\nPass the result to another tool:\n  hyperbdrctl --output json config get\n\nIf you need to update the default configuration after reviewing it, continue with:\n  hyperbdrctl config set \\\n    --host https://example:10443 \\\n    --username <username> \\\n    --password <password>",
	"cmd.config.get.notes":                 "- This command is local-only and does not call the remote API.\n- Use `--output json` when another tool needs the raw field names.",
	"cmd.config.get.related":               "./hyperbdrctl config set --help",
	"cmd.config.get.next_steps":            "./hyperbdrctl config set \\\n  --host https://example:10443 \\\n  --username admin \\\n  --password secret",
	"cmd.config.set.short":                 "Validate and save local CLI configuration",
	"cmd.config.set.long":                  "Merge the current command-line values with any saved configuration, verify the final credentials by logging in, then write the normalized configuration and token cache.",
	"cmd.config.set.examples":              "# Initial login and save\n./hyperbdrctl config set \\\n  --host https://example:10443 \\\n  --username admin \\\n  --password secret\n\n# Update scene and output on top of saved credentials\n./hyperbdrctl config set \\\n  --scene migration \\\n  --lang zh_cn \\\n  --output json",
	"cmd.config.set.usage_line":            "hyperbdrctl config set [flags]",
	"cmd.config.set.usage_notes":           "Before running this command, prepare the platform address, login username, and password for the target environment.\n\nInitialize the local configuration for the first time:\n  hyperbdrctl config set \\\n    --host https://example:10443 \\\n    --username <username> \\\n    --password <password>\n\nIf host, username, and password are already saved, you can update only the default scene, language, or output format:\n  hyperbdrctl config set \\\n    --scene migration \\\n    --lang zh_cn \\\n    --output json\n\nIf a field is omitted from the command line, the CLI fills it according to the following priority order:\n  command-line flags > environment variables > config file > defaults\n\nEquivalent settings can be provided through environment variables. Common environment variables include:\n  HYPERBDR_HOST\n  HYPERBDR_USERNAME\n  HYPERBDR_PASSWORD\n  HYPERBDR_SCENE\n  HYPERBDR_LANG\n  HYPERBDR_OUTPUT\n  HYPERBDR_INSECURE\n  HYPERBDR_DEBUG\n\nUsing Bash as an example, set the environment variables before saving:\n  export HYPERBDR_HOST=https://example:10443\n  export HYPERBDR_USERNAME=<username>\n  export HYPERBDR_PASSWORD=<password>\n  hyperbdrctl config set\n\nThe CLI validates the login before saving; if login fails, the new configuration is not saved.\n\nTo confirm the saved result, continue with:\n  hyperbdrctl config get\n\nAfter saving, run the following command to verify that subsequent commands use the new defaults:\n  hyperbdrctl host list",
	"cmd.config.set.notes":                 "- Pass host, credentials, scene, and TLS behavior through this command's local flags.\n- If login fails, the new configuration is not saved.\n- Use `--insecure` only for explicit test environments that intentionally skip TLS verification.",
	"cmd.config.set.minimum_flags":         "To initialize a new local configuration, provide:\n  --host\n  --username\n  --password",
	"cmd.config.set.automatic_behavior":    "- If a field is omitted on the current command line, `config set` resolves it through environment variables, saved config, and defaults before validation.\n- If host, username, and password are already saved, you can update scene, language, or output without resending credentials.\n- The CLI logs in with the fully merged candidate configuration before writing the new config and token cache.",
	"cmd.config.set.workflow":              "1. Gather the platform address, login username, and password for the target environment.\n2. Run `config set` with the required local flags on the same command line.\n3. Re-run `config get` to confirm the saved defaults and masked password output.",
	"cmd.config.set.common_optional_flags": "- `--scene`: Persist the default platform scene (`dr` or `migration`).\n- `--lang`: Persist the default CLI language and `X-LANG` request header.\n- `--output`: Persist the default output mode (`table` or `json`).\n- `--insecure`: Skip TLS certificate verification only for explicit test environments.\n- `--debug`: Print masked HTTP debug logs to stderr.",
	"cmd.config.set.related":               "./hyperbdrctl config get\n./hyperbdrctl config get --show-secret",
	"cmd.config.set.next_steps":            "./hyperbdrctl host list\n./hyperbdrctl boot-config get --id <host_id>",
}
